//! The vouching horizon (Genesis Mesh 1.8.0): the shared conformance suite
//! `vouching`, generated by the Python reference
//! (genesismesh/conformance/generate_vectors.py vouching) and copied
//! unchanged, run as the reference's `vouching_vectors.evaluate` runs it;
//! then the horizon helpers, `verify_record` judged now and the grant holder
//! given the NA's key history.

use genesis_mesh_sdk::{
    canonical::parse_timestamp,
    json,
    key_history::{
        verify_key_history, vouching_grace, NaKey, NaKeyHistory, NaKeys,
        SUCCESSION_HANDOVER_SECONDS, SUCCESSION_VOUCHING_GRACE_SECONDS,
    },
    verify::{verify_record, verify_record_for_present, VerifyRecordOptions},
    vouching::na_record_refusal,
    Value,
};

fn suite() -> Value {
    serde_json::from_str(include_str!("fixtures/vouching.json")).unwrap()
}

fn history(input: &Value) -> NaKeyHistory {
    verify_key_history(
        &input["genesis"],
        input["successions"].as_array().unwrap(),
        input["root_public_key"].as_str(),
    )
    .history
    .expect("the vector's key history verifies")
}

/// The vector's grace: its `grace_seconds`, or the most.
fn grace(input: &Value) -> i64 {
    vouching_grace(input["grace_seconds"].as_i64())
}

fn micros(value: &Value) -> i64 {
    parse_timestamp(value.as_str().unwrap())
        .unwrap()
        .timestamp_micros()
}

fn vector(id: &str) -> Value {
    suite()["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .find(|v| v["id"] == id)
        .unwrap()
        .clone()
}

#[test]
fn every_vouching_vector_matches_the_reference() {
    let suite = suite();
    assert_eq!(suite["suite"], "vouching");
    let vectors = suite["vectors"].as_array().unwrap();
    assert!(vectors.len() >= 32);
    for v in vectors {
        assert_eq!(v["kind"], "record_vouching", "{}", v["id"]);
        let input = &v["input"];
        let (h, g) = (history(input), grace(input));
        let model = v["model"].as_str().unwrap();
        let record = &input["record"];
        let now = Some(micros(&input["now"]));
        let got = json!({
            "at_record_time": na_record_refusal(model, record, &h, None, g).unwrap(),
            "now": na_record_refusal(model, record, &h, now, g).unwrap(),
        });
        assert_eq!(got, v["expected"], "{}: {}", v["id"], v["description"]);
    }
}

#[test]
fn the_horizon_is_the_end_the_hand_over_and_the_grace() {
    let succeeded = 1_800_000_000_000_000_i64;
    let valid_to = succeeded + 365 * 86_400_000_000;
    let key = |sequence, public_key: &str, from, succeeded_at, to, enforced| NaKey {
        key_sequence: sequence,
        public_key: public_key.into(),
        key_id: None,
        valid_from: from,
        succeeded_at,
        valid_to: to,
        valid_to_enforced: enforced,
    };
    let h = NaKeyHistory {
        sovereign_id: "TEST".into(),
        root_public_key: None,
        keys: vec![
            key(1, "old", None, Some(succeeded), None, false),
            key(2, "new", Some(succeeded), None, Some(valid_to), true),
        ],
        succession_digests: vec![],
    };
    let g = 3600;
    let horizon = succeeded + (SUCCESSION_HANDOVER_SECONDS + g) * 1_000_000;
    assert_eq!(h.vouches_until("old", g), Some(horizon));
    assert!(!h.record_outlives_key("old", horizon - 1, g));
    assert!(h.record_outlives_key("old", horizon, g));
    assert_eq!(
        h.keys_vouching_at(succeeded - 1, horizon - 1, g),
        vec!["old".to_owned()]
    );
    assert!(h.keys_vouching_at(succeeded - 1, horizon, g).is_empty());
    // The new key ends at its enforced valid_to; a key outside the history has no horizon.
    assert_eq!(
        h.vouches_until("new", g),
        Some(valid_to + (SUCCESSION_HANDOVER_SECONDS + g) * 1_000_000)
    );
    assert_eq!(h.vouches_until("stranger", g), None);
    // The published grace only shortens.
    assert_eq!(vouching_grace(None), SUCCESSION_VOUCHING_GRACE_SECONDS);
    assert_eq!(vouching_grace(Some(g)), g);
    assert_eq!(
        vouching_grace(Some(10 * 86_400)),
        SUCCESSION_VOUCHING_GRACE_SECONDS
    );
    assert_eq!(vouching_grace(Some(-5)), 0);
    // Keys valid at every time have no horizon.
    let any = NaKeys::from(vec!["old".to_owned()]);
    assert!(!any.outlives("old", i64::MAX, g));
    assert_eq!(any.key_sequence("old"), 0);
    let history = NaKeys::from(h.clone());
    assert!(history.outlives("old", horizon, g));
    assert_eq!(history.key_sequence("new"), 2);
    assert_eq!(
        history.vouching_at(Some(succeeded - 1), horizon, g),
        Vec::<String>::new()
    );
}

#[test]
fn verify_record_judges_attestations_and_grants_for_the_present_with_now() {
    for slug in ["attestation", "grant"] {
        let inside = vector(&format!("{slug}-old-key-within-grace"));
        let past = vector(&format!("{slug}-old-key-after-horizon"));
        let options = VerifyRecordOptions {
            key_history: Some(history(&inside["input"])),
            ..VerifyRecordOptions::default()
        };
        let for_present = |v: &Value| {
            let input = &v["input"];
            let now = parse_timestamp(input["now"].as_str().unwrap()).unwrap();
            verify_record_for_present(slug, &input["record"], &options, now, grace(input))
        };
        let checked = for_present(&inside);
        assert!(checked.verified, "{slug} inside the grace: {checked:?}");
        let refused = for_present(&past);
        assert!(!refused.verified);
        assert_eq!(refused.reason, "outlives_key", "{slug}");
        // At its own time it still verifies.
        assert!(
            verify_record(slug, &past["input"]["record"], &options).verified,
            "{slug}"
        );
    }
}

#[test]
fn a_grant_that_starts_more_than_24_hours_after_its_issue_is_refused() {
    for id in [
        "grant-valid-from-beyond-max-na-1",
        "grant-valid-from-beyond-max-na-2",
    ] {
        let v = vector(id);
        let options = VerifyRecordOptions {
            key_history: Some(history(&v["input"])),
            ..VerifyRecordOptions::default()
        };
        assert!(
            !verify_record("grant", &v["input"]["record"], &options).verified,
            "{id}"
        );
    }
}

// ── The grant holder, given the NA's key history ─────────────────────────────

#[cfg(feature = "client")]
mod holder {
    use super::*;
    use base64::{engine::general_purpose::STANDARD, Engine as _};
    use chrono::Utc;
    use genesis_mesh_sdk::{
        canonical::{python_timestamp, received_canonical},
        load_signing_key, public_key_from_seed, sign_canonical, ExecutionRecorder, GrantHolder,
    };

    const OLD_SEED: [u8; 32] = [3; 32];
    const NEW_SEED: [u8; 32] = [9; 32];
    const BEARER_SEED: [u8; 32] = [5; 32];

    fn key_of(seed: [u8; 32]) -> String {
        public_key_from_seed(&STANDARD.encode(seed)).unwrap()
    }

    fn recorder() -> ExecutionRecorder {
        ExecutionRecorder::new("device-b", "executor-b", &STANDARD.encode(BEARER_SEED)).unwrap()
    }

    fn signed(model: &str, mut record: Value, seed: [u8; 32], key_id: &str) -> Value {
        let canonical = received_canonical(model, &record).unwrap();
        let key = load_signing_key(&STANDARD.encode(seed)).unwrap();
        let signature = sign_canonical(&canonical, key_id, &key);
        if model == "SovereignRevocationFeed" {
            record["signatures"] = json!([signature]);
        } else {
            record["signature"] = signature;
        }
        record
    }

    fn at(minutes: i64) -> String {
        python_timestamp(Utc::now() + chrono::Duration::minutes(minutes))
    }

    /// The old key succeeded `succeeded_minutes_ago`.
    fn two_keys(succeeded_minutes_ago: i64) -> NaKeyHistory {
        let succeeded =
            (Utc::now() - chrono::Duration::minutes(succeeded_minutes_ago)).timestamp_micros();
        NaKeyHistory {
            sovereign_id: "sovereign-c".into(),
            root_public_key: None,
            keys: vec![
                NaKey {
                    key_sequence: 1,
                    public_key: key_of(OLD_SEED),
                    key_id: Some("na-1".into()),
                    valid_from: None,
                    succeeded_at: Some(succeeded),
                    valid_to: None,
                    valid_to_enforced: false,
                },
                NaKey {
                    key_sequence: 2,
                    public_key: key_of(NEW_SEED),
                    key_id: Some("na-2".into()),
                    valid_from: Some(succeeded),
                    succeeded_at: None,
                    valid_to: Some(succeeded + 365 * 86_400_000_000),
                    valid_to_enforced: true,
                },
            ],
            succession_digests: vec![],
        }
    }

    fn grant(issued: i64, seed: [u8; 32], key_id: &str) -> (Value, Value) {
        let grant = signed(
            "CapabilityGrant",
            json!({
                "grant_id": "00000000-0000-4000-8000-000000000010",
                "bearer_key_id": "executor-b",
                "bearer_public_key": recorder().public_key(),
                "bearer_sovereign_id": "device-b",
                "capabilities": ["secret.rotate"],
                "basis_kind": "attestation",
                "basis_id": "00000000-0000-4000-8000-000000000001",
                "basis_digest": "e".repeat(64),
                "requester_sovereign_id": "vendor-acme",
                "provider_sovereign_id": "sovereign-c",
                "valid_from": at(issued),
                "valid_until": at(issued + 20 * 60),
                "max_uses": 3,
                "max_uses_per_time_token": 2,
                "parameter_envelope": {},
                "basis_checks": [],
                "policy_binding": {"policies": [], "policy_set_digest": "p", "gate_outcomes": [],
                                   "registry_gate_types": []},
                "issued_at": at(issued),
                "issuer_sovereign_id": "sovereign-c",
                "issued_by": key_id,
            }),
            seed,
            key_id,
        );
        let token = signed(
            "TimeToken",
            json!({
                "time_token_id": "00000000-0000-4000-8000-000000000030",
                "grant_id": "00000000-0000-4000-8000-000000000010",
                "use_sequence": 0,
                "issued_at": at(issued),
                "issuer_sovereign_id": "sovereign-c",
                "issued_by": key_id,
            }),
            seed,
            key_id,
        );
        (grant, token)
    }

    fn feed(sequence: u64, issued: i64, seed: [u8; 32], key_id: &str) -> Value {
        signed(
            "SovereignRevocationFeed",
            json!({
                "feed_id": format!("feed-{key_id}-{sequence}"),
                "issuer_sovereign_id": "sovereign-c",
                "sequence": sequence,
                "issued_at": at(issued),
                "revoked_attestation_ids": [],
                "revocation_reasons": {},
                "issued_by": key_id,
            }),
            seed,
            key_id,
        )
    }

    #[test]
    fn the_holder_refuses_a_grant_of_a_key_past_its_horizon() {
        // Issued by the old key 15 minutes ago, before its succession 10 minutes ago: inside the
        // grace, held.
        let (g, t) = grant(-15, OLD_SEED, "na-1");
        let holder = GrantHolder::new(g, t, recorder(), two_keys(10)).unwrap();
        let request = json!({});
        assert!(holder
            .check("secret.rotate", &request, None, Utc::now())
            .is_none());
        // With a one-minute grace, the hand-over and the grace have passed: it has ended.
        let shorter = holder.with_vouching_grace(60);
        let ended = shorter
            .check("secret.rotate", &request, None, Utc::now())
            .unwrap();
        assert_eq!(ended.code, "grant_expired");
        // The grace only shortens.
        let ended = shorter
            .with_vouching_grace(3600)
            .check("secret.rotate", &request, None, Utc::now())
            .unwrap();
        assert_eq!(ended.code, "grant_expired");
        // A key that ended more than the day's grace ago: refused when the holder is built.
        let (g, t) = grant(-(25 * 60 + 15), OLD_SEED, "na-1");
        let refused = GrantHolder::new(g, t, recorder(), two_keys(25 * 60 + 10)).unwrap_err();
        assert!(refused.to_string().contains("outlives_key"), "{refused}");
    }

    #[test]
    fn a_held_grant_ends_as_expired_once_its_key_passes_the_horizon() {
        let (g, t) = grant(-15, OLD_SEED, "na-1");
        let holder = GrantHolder::new(g, t, recorder(), two_keys(10))
            .unwrap()
            .with_vouching_grace(3600);
        let request = json!({});
        assert!(holder
            .check("secret.rotate", &request, None, Utc::now())
            .is_none());
        // Fifty minutes from now the hand-over and the hour's grace have passed; the grant itself
        // (valid for 20 hours) has not ended.
        let later = Utc::now() + chrono::Duration::minutes(56);
        let ended = holder
            .check("secret.rotate", &request, None, later)
            .unwrap();
        assert_eq!(ended.code, "grant_expired");
    }

    #[test]
    fn the_holder_orders_feeds_by_their_signers_key_then_by_sequence() {
        let (g, t) = grant(-5, NEW_SEED, "na-2");
        let mut holder = GrantHolder::new(g, t, recorder(), two_keys(10))
            .unwrap()
            .with_vouching_grace(3600);
        // A feed the old key signed inside its window, with a forged high sequence.
        holder
            .set_feed(feed(1_000_000, -11, OLD_SEED, "na-1"))
            .unwrap();
        // The new key's feed replaces it although its sequence is lower...
        holder.set_feed(feed(12, -4, NEW_SEED, "na-2")).unwrap();
        assert_eq!(holder.state().feed.as_ref().unwrap()["sequence"], 12);
        // ...and an old-key feed no longer replaces a new-key one, whatever its sequence.
        assert!(holder
            .set_feed(feed(2_000_000, -12, OLD_SEED, "na-1"))
            .is_err());
        // Within one key, a lower sequence never replaces a higher one.
        assert!(holder.set_feed(feed(11, -3, NEW_SEED, "na-2")).is_err());
        holder.set_feed(feed(13, -2, NEW_SEED, "na-2")).unwrap();
        // Keys valid at every time keep the old order, by sequence alone.
        let (g, t) = grant(-5, NEW_SEED, "na-2");
        let mut flat =
            GrantHolder::new(g, t, recorder(), vec![key_of(OLD_SEED), key_of(NEW_SEED)]).unwrap();
        flat.set_feed(feed(1_000_000, -11, OLD_SEED, "na-1"))
            .unwrap();
        assert!(flat.set_feed(feed(12, -4, NEW_SEED, "na-2")).is_err());
    }
}
